import { FileDown } from 'lucide-react';
import { withQuery } from '@/lib/search-params';
import { Button, type ButtonProps } from '@/components/ui/button';

/** Download link for reflection PDFs (generated by the API, sent as an attachment). */
export function PdfLink({
  reflectionId,
  query,
  label = 'Download PDF',
  variant = 'outline',
  size = 'default',
}: {
  /** Single reflection; omit to export all reflections matching `query`. */
  reflectionId?: string;
  query?: Record<string, string | undefined>;
  label?: string;
  variant?: ButtonProps['variant'];
  size?: ButtonProps['size'];
}) {
  const href = reflectionId
    ? `/api/v1/reflections/${reflectionId}/pdf`
    : withQuery('/api/v1/reflections/export.pdf', query ?? {});
  return (
    <Button asChild variant={variant} size={size}>
      <a href={href} download>
        <FileDown aria-hidden /> {label}
      </a>
    </Button>
  );
}
